/* Elder usability validation harness: task timing, errors, accessibility checks and export. */
(function(){
  'use strict';
  const KEY='ccner-usability-validation';
  const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{"runs":[]}')}catch(_){return{runs:[]}}};
  const save=v=>localStorage.setItem(KEY,JSON.stringify(v));
  let active=null;
  const tasks=[['home_start','Start today’s cognitive session'],['reminders_open','Open Reminders'],['reminder_add','Create a reminder'],['progress_open','Open Progress'],['language_change','Change preferred language'],['voice_start','Use Talk to Momo'],['game_exit','Exit a game safely']];
  function begin(){active={id:crypto.randomUUID(),startedAt:Date.now(),tasks:tasks.map(([id,label])=>({id,label,status:'not_started',startedAt:null,completedAt:null,errors:0})),errors:0,notes:[]};const s=read();s.runs.unshift(active);s.runs=s.runs.slice(0,20);save(s);render()}
  function complete(id){if(!active)return;const t=active.tasks.find(x=>x.id===id);if(!t)return;if(!t.startedAt)t.startedAt=Date.now();t.status='completed';t.completedAt=Date.now();save(read());}
  function error(id){if(!active)return;const t=active.tasks.find(x=>x.id===id);if(t)t.errors++;active.errors++;save(read())}
  function startTask(id){if(!active)return;const t=active.tasks.find(x=>x.id===id);if(t&&!t.startedAt){t.startedAt=Date.now();t.status='in_progress';save(read())}}
  function domAudit(){
    const issues=[];const all=[...document.querySelectorAll('button,input,select,textarea,a,[role="button"]')];
    all.forEach((el,i)=>{const r=el.getBoundingClientRect();if(r.width>0&&r.height>0&&(r.width<44||r.height<44))issues.push(`Touch target ${i+1} is ${Math.round(r.width)}×${Math.round(r.height)}px; target should be at least 44×44px.`);if((el.matches('button,a,[role="button"]'))&&!String(el.getAttribute('aria-label')||el.textContent||'').trim())issues.push(`Interactive control ${i+1} has no accessible name.`)});
    const body=getComputedStyle(document.body);const font=parseFloat(body.fontSize);if(font<16)issues.push(`Base font size is ${font}px; elderly mode should be at least 16px.`);
    if(!document.querySelector('main'))issues.push('Missing main landmark.');
    return {passed:issues.length===0,issues,checkedAt:new Date().toISOString(),interactiveElements:all.length};
  }
  function render(){let p=document.getElementById('usabilityPanel');if(!p){p=document.createElement('section');p.id='usabilityPanel';p.className='p2-panel';document.body.appendChild(p)}const run=active||read().runs?.[0];const audit=domAudit();p.innerHTML='<div class="p2-sheet"><button class="p2-close" aria-label="Close">×</button><span class="p2-eyebrow">ELDERLY USABILITY VALIDATION</span><h2>Usability test mode</h2><p class="p2-sub">Run this with an older adult on the actual phone/tablet. This records task completion, time and errors without storing names or audio.</p><div class="ph-card"><strong>Automated accessibility audit</strong><p class="ph-test">'+(audit.passed?'✓ No basic DOM accessibility issues detected.':'⚠ '+audit.issues.length+' issue(s) detected.')+'</p>'+(audit.issues.length?'<ul>'+audit.issues.slice(0,12).map(x=>'<li>'+x+'</li>').join('')+'</ul>':'')+'</div><div class="ph-card"><strong>Human task run</strong><div class="ph-actions"><button class="ph-btn" data-us="begin">Start new test</button><button class="ph-btn secondary" data-us="export">Export validation log</button></div>'+(run?run.tasks.map(t=>`<div class="ph-row"><div><strong>${t.label}</strong><small>${t.status}${t.startedAt&&t.completedAt?' · '+Math.round((t.completedAt-t.startedAt)/1000)+'s':''} · errors ${t.errors}</small></div><button class="ph-btn secondary" data-complete="${t.id}">Complete</button></div>`).join(''):'<p class="p1-muted">No test run yet.</p>')+'</div><div class="ph-card"><strong>Validation rule</strong><p class="ph-test">Software instrumentation can verify accessibility and task mechanics. Real elderly usability validation requires actual participants, consent, observation and a documented study; this tool intentionally does not pretend synthetic tests are human evidence.</p></div></div>';p.querySelector('.p2-close').onclick=()=>p.remove();p.querySelector('[data-us="begin"]')?.addEventListener('click',begin);p.querySelector('[data-us="export"]')?.addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(read(),null,2)],{type:'application/json'}));a.download='ccner-elderly-usability-validation.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});p.querySelectorAll('[data-complete]').forEach(b=>b.addEventListener('click',()=>{complete(b.dataset.complete);render()}))}
  function boot(){const home=document.getElementById('homeView');if(!home||document.getElementById('usabilityButton'))return;const b=document.createElement('button');b.id='usabilityButton';b.className='p2-btn p2-dashboard-launch';b.textContent='🧓 Elderly usability test';b.onclick=render;home.appendChild(b);document.addEventListener('click',e=>{const a=e.target.closest('[data-usability-action]');if(!a)return;const id=a.dataset.usabilityAction;if(id==='error')error(a.dataset.task);else if(id==='start')startTask(a.dataset.task);else complete(id)})}
  window.CCNERUsability={begin,complete,error,startTask,domAudit,render,getData:read};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
